def filters_from_profiles(apps, schema_editor):
    """Существующим людям заполняем фильтры из анкеты, чтобы лента не изменилась."""
    Profile = apps.get_model("accounts", "Profile")
    SearchFilters = apps.get_model("matching", "SearchFilters")
    for profile in Profile.objects.all().iterator():
        SearchFilters.objects.get_or_create(
            user_id=profile.user_id,
            defaults={
                "city_id": profile.city_id,
                "rent_max": profile.budget_max,
                "areas": profile.preferred_districts,
                "available_by": profile.move_in_date,
                "pets_needed": profile.has_pets,
                "smoking_needed": profile.smoker,
            },
        )


